(root/'quality_checks.json').write_text(json.dumps(quality,indent=2));print(json.dumps({'completed':s['completed'],'failed':s['failed'],'spearman_rho':s['spearman_rho'],'review_shortlist':s['review_shortlist'],'quality_checks':quality}),flush=True)
